async function getVideoDuration(file){return new Promise((resolve,reject)=>{const url=URL.createObjectURL(file),v=document.createElement('video');v.preload='metadata';v.onloadedmetadata=()=>{const d=v.duration;URL.revokeObjectURL(url);resolve(Number.isFinite(d)?d:0)};v.onerror=()=>{URL.revokeObjectURL(url);reject(new Error('video metadata'))};v.src=url})}
async function saveMedia(input){
  let files=[...(input.files||[])];if(!files.length)return;const maxPick=Number(input.dataset.maxPick||MAX_FILES_PER_PICK);if(files.length>maxPick){input.value='';alert(t(`Selecciona hasta ${maxPick} archivo(s) a la vez. No se agregó ningún archivo.`,`Select up to ${maxPick} file(s) at a time. No files were added.`));return}
  const unit=input.closest('.unit'),key=input.dataset.evidence;touchUnit(unit);const all=await idbGetAllMedia(),unitMedia=all.filter(x=>x.unitId===unit.dataset.unitId),maxTotal=Number(input.dataset.maxTotal||0);
  const existingForKey=unitMedia.filter(x=>x.key===key);
  if(maxTotal===1&&files.length===1){for(const r of existingForKey)await idbDeleteMedia(r.id)}
  else if(maxTotal>0&&existingForKey.length+files.length>maxTotal){input.value='';alert(t(`Este espacio admite un máximo de ${maxTotal} archivo(s) de evidencia. Elimina uno antes de agregar otro.`,`This evidence slot allows a maximum of ${maxTotal} file(s). Delete one before adding another.`));return}
  const isFunctionalVideo=key==='functional-video';
  let functionalVideoCount=unitMedia.filter(x=>x.key==='functional-video'&&String(x.type||'').startsWith('video/')).length;setSave('saving',t('Guardando evidencia…','Saving evidence…'),t(`${files.length} archivo(s).`,`${files.length} file(s).`));
  try{for(const file of files){if(String(file.type||'').startsWith('video/')){if(file.size>MAX_VIDEO_BYTES){alert(t(`El video “${file.name}” excede 50 MB y no se guardó.`,`Video “${file.name}” exceeds 50 MB and was not saved.`));continue}if(isFunctionalVideo&&functionalVideoCount>=MAX_FUNCTIONAL_VIDEOS_PER_UNIT){alert(t('Ya hay 3 videos funcionales guardados para esta unidad. Elimina uno antes de agregar otro.','There are already 3 functional-test videos stored for this unit. Delete one before adding another.'));continue}let dur=0;try{dur=await getVideoDuration(file)}catch(e){}const maxSeconds=isFunctionalVideo?MAX_FUNCTIONAL_VIDEO_SECONDS:MAX_FINDING_VIDEO_SECONDS;if(dur>maxSeconds+.25){alert(t(`El video “${file.name}” dura más de ${maxSeconds} segundos y no se guardó.`,`Video “${file.name}” is longer than ${maxSeconds} seconds and was not saved.`));continue}if(isFunctionalVideo)functionalVideoCount++}await idbPut(MEDIA,{id:uid(),unitId:unit.dataset.unitId,key,name:file.name||t('evidencia','evidence'),type:file.type||'',size:file.size||0,createdAt:nowIso(),blob:file})}input.value='';await restoreMediaPreviews(unit);await saveNow();updateAll(unit)}catch(e){console.error(e);setSave('bad',t('Error guardando evidencia','Error saving evidence'),t('La información escrita sigue disponible; intenta agregar la evidencia nuevamente.','Written information is still available; try adding the evidence again.'))}
}
async function restoreMediaPreviews(unit){try{const all=await idbGetAllMedia();for(const grid of $$(unit,'[data-preview-keys]'))renderMediaGrid(unit,grid,all);updateAll(unit)}catch(e){console.warn(e)}}
function renderMediaGrid(unit,grid,all){const keys=(grid.dataset.previewKeys||'').split('|').filter(Boolean);const recs=all.filter(r=>r.unitId===unit.dataset.unitId&&keys.includes(r.key));grid.innerHTML='';for(const rec of recs){const card=document.createElement('div');card.className='photo-preview';let url='';if(rec.type.startsWith('image/'))url=URL.createObjectURL(rec.blob);card.innerHTML=(url?`<img src="${url}" alt="">`:`<div class="file-meta"><b>VIDEO</b> · ${escapeHtml(rec.name)}</div>`)+`<button type="button" class="delete-media">×</button><div class="file-meta">${escapeHtml(rec.name)}</div>`;card.querySelector('.delete-media').onclick=async()=>{if(confirm(t('¿Eliminar esta evidencia?','Delete this evidence?'))){await idbDeleteMedia(rec.id);if(url)URL.revokeObjectURL(url);touchUnit(unit);await restoreMediaPreviews(unit);scheduleSave()}};grid.appendChild(card)}}

async function shareOrDownloadBlob(name,blob){const file=new File([blob],name,{type:blob.type||'application/octet-stream'});try{if(navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:name});return true}}catch(e){if(e.name!=='AbortError')console.warn(e)}try{const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),2000);return true}catch(e){console.error(e);return false}}
async function shareOrDownloadText(name,text,type){return shareOrDownloadBlob(name,new Blob([text],{type}))}
async function backup(){syncStateFromDom();await saveNow();syncStateFromDom();const ok=await shareOrDownloadText((LANG==='es'?'clover-inspeccion-':'clover-inspection-')+($('#date').value||'session')+'.json',JSON.stringify(state,null,2),'application/json');$('#bottomActionStatus').textContent=ok?t('Respaldo listo para guardar/compartir.','Backup ready to save/share.'):t('No se pudo generar el respaldo.','Could not generate backup.')}
function displayField(key,value){if(key==='power')return optionLabel(SELECTS.power,value);if(key==='tires')return optionLabel(SELECTS.tires,value);if(key==='mast')return optionLabel(SELECTS.mast,value);if(key==='attachment')return optionLabel(SELECTS.attachment,value);if(key==='operational')return optionLabel(SELECTS.operational,value);if(key==='equipmentCategory')return optionLabel([['',''],...EQUIPMENT_CATEGORIES],value);if(key==='equipmentType'){for(const arr of Object.values(EQUIPMENT_TYPES)){const x=arr.find(v=>v[0]===value);if(x)return x[1]}return value||''}if(key==='forkLength')return value==='other'?t('Otro','Other'):value?value+'"':'';return value||''}
async function exportCSV(){syncStateFromDom();const rows=[[t('Cliente','Client'),t('Ubicación','Location'),t('Fecha','Date'),t('Técnico','Technician'),t('Unidad','Unit'),t('Serie','Serial'),t('Marca','Make'),t('Modelo','Model'),t('ID pregunta','Question ID'),t('Sección','Section'),t('Ítem','Item'),t('Estado','Status'),t('Observación','Observation'),t('Acción / clasificación','Action / classification'),t('Notas','Notes')]];for(const u of state.units){for(const c of u.checks.filter(c=>c.applicable!==false&&isFindingCode(c.statusCode))){const item=ITEM_BY_ID.get(c.questionId);if(!item)continue;rows.push([state.session.client||'',state.session.location||'',state.session.date||'',state.session.tech||'',u.fields.clientUnit||'',u.fields.serial||'',effectiveFieldValue(u.fields,'make')||'',effectiveFieldValue(u.fields,'model')||'',item.id,item.sectionTitle,item.label,STATUS_LABELS[c.statusCode]||c.statusCode,c.observation||'',ACTION_LABELS[c.classificationCode]||c.classificationCode||'',c.notes||''])}}
  const csv='\ufeff'+rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');const ok=await shareOrDownloadText(LANG==='es'?'clover-hallazgos.csv':'clover-findings.csv',csv,'text/csv;charset=utf-8');$('#bottomActionStatus').textContent=ok?t('CSV listo para guardar/compartir.','CSV ready to save/share.'):t('No se pudo generar el CSV.','Could not generate CSV.')}

